// Measures reading .msh files (NFR-003-01, NFR-003-02). Not part of ctest:
// run it on a Release build with large files generated by
//   python tests/data/gmsh/generate_test_meshes.py --large <folder>
//
// Usage: bench_gmsh_read <file.msh> [<file.msh> ...]

#include <fem/core/element_type.hpp>
#include <fem/core/mesh.hpp>
#include <fem/io/gmsh_reader.hpp>

#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <span>

namespace {

int run(int argc, char** argv)
{
    const std::span<char* const> args(argv, static_cast<std::size_t>(argc));
    if (args.size() < 2) {
        std::fputs("usage: bench_gmsh_read <file.msh> [<file.msh> ...]\n", stderr);
        return EXIT_FAILURE;
    }

    int status = EXIT_SUCCESS;
    for (const char* name : args.subspan(1)) {
        const std::filesystem::path path(name);
        const auto start = std::chrono::steady_clock::now();
        const auto result = fem::io::readGmsh(path);
        const std::chrono::duration<double> elapsed = std::chrono::steady_clock::now() - start;
        if (!result) {
            std::fprintf(stderr, "%s\n", result.error().message.c_str());
            status = EXIT_FAILURE;
            continue;
        }

        const fem::core::Mesh& mesh = result->mesh;
        // Raw data: coordinates in double and connectivity in 32-bit integers.
        double raw = static_cast<double>(mesh.nodeCount()) * 3 * sizeof(double);
        for (const fem::core::ElementBlock& block : mesh.blocks()) {
            raw += static_cast<double>(block.connectivity.size()) * sizeof(std::int32_t);
        }
        const auto bytes = static_cast<double>(mesh.memoryUsage());
        std::printf("%s\n  %.2f s, %d nodes, %d elements (%d Tet4)\n"
                    "  mesh memory %.1f MB, raw data %.1f MB, ratio %.2f\n",
                    name, elapsed.count(), mesh.nodeCount(), mesh.elementCount(),
                    mesh.elementCount(fem::core::ElementType::Tet4), bytes / 1e6, raw / 1e6,
                    bytes / raw);
    }
    return status;
}

} // namespace

int main(int argc, char* argv[])
{
    try {
        return run(argc, argv);
    } catch (...) {
        std::fputs("bench_gmsh_read: fatal error\n", stderr);
        return EXIT_FAILURE;
    }
}
